'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const {blockers}=require('../issue-reconciliation-report.cjs');
const sha='a'.repeat(40),head='b'.repeat(40);
const pr={body:'## Acceptance criteria\n- [x] Verified\n\nDev-Completes: #320',head:{sha:head},merge_commit_sha:sha};
const issue={number:320,labels:[{name:'dev-acceptance-verified'}]};
const checks=['verify','analyze (javascript-typescript)','analyze (csharp)'].map(name=>({name,head_sha:head,conclusion:'success'}));
const deployment={sha,conclusion:'success',smokePassed:true};
const valid={pr,issue,checks,deployment,projectMember:true,tokenConfigured:true};
test('complete evidence clears blockers',()=>assert.deepEqual(blockers(valid),[]));
test('partial PR blocked',()=>assert.match(blockers({...valid,pr:{...pr,body:'Refs #320'}}).join(';'),/Dev-Completes/));
test('owner approval required',()=>assert.match(blockers({...valid,issue:{...issue,labels:[]}}).join(';'),/approval/));
test('missing token blocked',()=>assert.match(blockers({...valid,tokenConfigured:false}).join(';'),/TOKEN/));
test('missing project blocked',()=>assert.match(blockers({...valid,projectMember:false}).join(';'),/Project/));
test('stale SHA blocked',()=>assert.match(blockers({...valid,deployment:{...deployment,sha:head}}).join(';'),/deployment/));
test('missing smoke blocked',()=>assert.match(blockers({...valid,deployment:{...deployment,smokePassed:false}}).join(';'),/smoke/));
test('failing security scan blocked',()=>assert.match(blockers({...valid,checks:checks.slice(0,2)}).join(';'),/csharp/));
test('unchecked acceptance criteria blocked',()=>assert.match(blockers({...valid,pr:{...pr,body:'## Acceptance criteria\n- [ ] Incomplete\n\nDev-Completes: #320'}}).join(';'),/checklist/));
test('same evidence produces same blockers',()=>assert.deepEqual(blockers(valid),blockers(valid)));
